import sys
import math

def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def can_form_binary_tree(nodes):
    n = len(nodes)
    for i in range(n):
        for j in range(n):
            if i != j and nodes[i][1] <= nodes[j][1]:
                return False
    return True

def build_binary_tree(nodes):
    n = len(nodes)
    dp = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 0

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                cost = distance(nodes[i][0], nodes[i][1], nodes[j][0], nodes[j][1])
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] + cost)

    return dp[0][n - 1]

def main():
